create extension if not exists "pgcrypto";
create type public.user_role as enum ('admin','manager','seller');create type public.pipeline_stage as enum ('lead_new','follow_up','closing','won','financing','consortium','future_sale','lost');create type public.lead_temperature as enum ('hot','warm','cold');
create table if not exists public.profiles(id uuid primary key default gen_random_uuid(),user_id uuid unique not null references auth.users(id) on delete cascade,full_name text not null,email text,avatar_url text,role public.user_role not null default 'seller',phone text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.motorcycle_models(id uuid primary key default gen_random_uuid(),name text not null,category text,description text,active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),full_name text not null,cpf text,phone text,whatsapp text,email text,birth_date date,city text,state text,address text,motorcycle_model_id uuid references public.motorcycle_models(id),pipeline_stage public.pipeline_stage not null default 'lead_new',temperature public.lead_temperature not null default 'warm',lead_source text,estimated_value numeric,available_down_payment numeric,desired_installment numeric,has_trade_in boolean not null default false,trade_in_model text,trade_in_value numeric,assigned_to uuid references public.profiles(id),notes text,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),last_contact_at timestamptz,next_follow_up_at timestamptz);
create table if not exists public.customer_interactions(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,user_id uuid references public.profiles(id),type text not null,description text not null,created_at timestamptz not null default now());
create table if not exists public.appointments(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,user_id uuid references public.profiles(id),title text not null,type text not null,scheduled_at timestamptz not null,notes text,status text not null default 'scheduled',created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.sales_pipeline_history(id uuid primary key default gen_random_uuid(),customer_id uuid not null references public.customers(id) on delete cascade,user_id uuid references public.profiles(id),from_stage public.pipeline_stage,to_stage public.pipeline_stage not null,created_at timestamptz not null default now());
alter table public.profiles enable row level security;alter table public.customers enable row level security;alter table public.customer_interactions enable row level security;alter table public.appointments enable row level security;alter table public.sales_pipeline_history enable row level security;alter table public.motorcycle_models enable row level security;
create or replace function public.current_role() returns public.user_role language sql stable security definer set search_path=public as $$select coalesce((select role from public.profiles where user_id=auth.uid()),'seller'::public.user_role)$$;
create policy "models authenticated read" on public.motorcycle_models for select to authenticated using (active=true);
create policy "profiles own read" on public.profiles for select to authenticated using (user_id=auth.uid() or public.current_role() in ('admin','manager'));
create policy "customers scoped read" on public.customers for select to authenticated using (assigned_to in (select id from public.profiles where user_id=auth.uid()) or public.current_role() in ('admin','manager'));
create policy "customers scoped insert" on public.customers for insert to authenticated with check (assigned_to in (select id from public.profiles where user_id=auth.uid()) or public.current_role() in ('admin','manager'));
create policy "customers scoped update" on public.customers for update to authenticated using (assigned_to in (select id from public.profiles where user_id=auth.uid()) or public.current_role() in ('admin','manager'));
create policy "interactions scoped" on public.customer_interactions for all to authenticated using (customer_id in (select id from public.customers where assigned_to in (select id from public.profiles where user_id=auth.uid())) or public.current_role() in ('admin','manager')) with check (customer_id in (select id from public.customers where assigned_to in (select id from public.profiles where user_id=auth.uid())) or public.current_role() in ('admin','manager'));
create policy "appointments scoped" on public.appointments for all to authenticated using (user_id in (select id from public.profiles where user_id=auth.uid()) or public.current_role() in ('admin','manager')) with check (user_id in (select id from public.profiles where user_id=auth.uid()) or public.current_role() in ('admin','manager'));
create policy "pipeline history scoped" on public.sales_pipeline_history for select to authenticated using (customer_id in (select id from public.customers where assigned_to in (select id from public.profiles where user_id=auth.uid())) or public.current_role() in ('admin','manager'));
